"""Derive SkyyWardrobe/build_skyywardrobe_0.2.10.py from the SET pin 0.2.9 (build_skyywardrobe_0.2.9.py, GENERATED by
tools/wardrobe_0_2_9_patch.py; 0.2.9 stays untouched) AND SkyyWardrobe/test_skyywardrobe_0.2.10.py from test_skyywardrobe_0.2.9.py.
Edit THIS file, never the generated scripts: python tools/wardrobe_0_2_10_patch.py, then python SkyyWardrobe/build_skyywardrobe_0.2.10.py
(never --deploy from an agent). Test: python SkyyWardrobe/test_skyywardrobe_0.2.10.py
Every anchor is asserted once; at the end every change is undone on a copy and compared with the source (nothing else changed).

0.2.10 (2026-10-18, LEAN round) - Skyy (screenshot of Storage > Requip > PETS tab): "can we make this show the pet icon".
Until 0.2.9 every pet row of the pet / summon picker ("Common Dog Lv 25", "Common Gecko Lv 1", Mouflon, Rat) and the loadout's picked
pet / summon cell under "PET, SUMMON + ABILITIES" showed the same icon (WdBridge.PET_ICON = Farming_Collar).
  1. WdPage.petPic(label, fallback): the pet's OWN portrait item Skyy_PetIcon_<Kind> (SkyyPets 0.4.0+, hidden icon items, one per kind).
     The bridge (pets:fn:petName, SkyyPets 0.4.4) answers only the label "<Rarity> <kind name> Lv N" - NO icon id and no kind (the pet
     id is random), and pets:fn:owned is not published; SkyyPets is NOT changed (a later Pets round could add the icon id to the
     bridge). The label's name is SkyyPets' own PetKind.display(kind) (fixed, not a Server Setup value): the first word dropped when it
     is a rarity word (Common .. Mythic, Unknown), the rest joined without spaces ("Crystal Golem" -> CrystalGolem; SkyyPets' one NAMES
     entry "Skeleton Archer" -> Skeleton), else joined with "_". Each candidate goes through the existing ItemIcon rule WdPage.safe
     (a plain [A-Za-z0-9_] id the client KNOWS, else "") - so an unknown kind, an older SkyyPets without portraits, an odd label = the
     fallback (the 0.2.9 icon), never a client warning.
  2. Used in every place Requip shows a picked pet: the picker rows (pet + summon slot) and the loadout's Pet / Summon cells. Unchanged on
     purpose: a Keep cell stays icon-less (0.2.3 fix a: "the icon-less look says it is not a pick"), a Gone pet keeps the fallback icon.
  No item, no saved data, no command, no bridge key changes. Rollback to 0.2.9: safe (the rows show the collar again). Needs nothing new.
Classes: WdPage (+ petPic; refViews / refList: bodies).
"""
import os

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
HERE = os.path.join(ROOT, "SkyyWardrobe")
LF = "\n"


class Patch(object):
    def __init__(self, src, dst, tag):
        raw = open(src, "rb").read()
        self.nl = "\r\n" if b"\r\n" in raw else "\n"
        assert self.nl == "\n" or raw.count(b"\r\n") == raw.count(b"\n"), "mixed line endings in " + src
        self.s = raw.decode("utf8").replace("\r\n", "\n")
        self.old = self.s
        self.src, self.dst, self.tag = src, dst, tag
        self.changes = []

    def has(self, t):
        return t in self.s

    def rep(self, old, new):
        n = self.s.count(old)
        assert n == 1, "%s anchor count %d: %s" % (self.tag, n, old[:140])
        assert self.s.count(new) == 0, "%s: the new text already exists: %s" % (self.tag, new[:100])
        self.s = self.s.replace(old, new, 1)
        self.changes.append((new, old))

    def finish(self):
        u = self.s
        for new, old in reversed(self.changes):
            assert u.count(new) == 1, "%s: a change is not unique any more: %s" % (self.tag, new[:100])
            u = u.replace(new, old, 1)
        assert u == self.old, "%s: the generated script differs from the source outside the recorded changes" % self.tag
        compile(self.s, self.dst, "exec")
        open(self.dst, "w", encoding="utf8", newline="").write(self.s.replace(LF, self.nl) if self.nl != LF else self.s)
        print("wrote", os.path.relpath(self.dst, ROOT), "(%d lines; source %d; %d changes, undo-compare OK)" % (self.s.count(LF), self.old.count(LF), len(self.changes)))


# ====================================================================================================================== THE BUILD
P = Patch(os.path.join(HERE, "build_skyywardrobe_0.2.9.py"), os.path.join(HERE, "build_skyywardrobe_0.2.10.py"), "build")
assert P.has('VERSION = "0.2.9"\n') and P.has("supply:fn:claims") and not P.has("Skyy_PetIcon_"), "the source must be the generated build_skyywardrobe_0.2.9.py"
REG0, SYS0 = P.s.count("registerCommand("), P.s.count("registerSystem(")

P.rep('"""SkyyWardrobe 0.2.9 "Requip" - build script GENERATED by tools/wardrobe_0_2_9_patch.py from build_skyywardrobe_0.2.8.py (edit the patch).\n',
      '"""SkyyWardrobe 0.2.10 "Requip" - build script GENERATED by tools/wardrobe_0_2_10_patch.py from build_skyywardrobe_0.2.9.py (edit the patch).\n'
      '0.2.10 (2026-10-18, Skyy: "can we make this show the pet icon"; full notes: tools/wardrobe_0_2_10_patch.py): the pet picker rows and the\n'
      'loadout\'s picked Pet / Summon cells show the pet\'s own SkyyPets portrait Skyy_PetIcon_<Kind> (kind read from the pets:fn:petName label;\n'
      'only an id the client knows, else the 0.2.9 icon). Test: python SkyyWardrobe/test_skyywardrobe_0.2.10.py\n'
      '0.2.9 = GENERATED by tools/wardrobe_0_2_9_patch.py from build_skyywardrobe_0.2.8.py.\n')
P.rep('VERSION = "0.2.9"\n', 'VERSION = "0.2.10"\n')
# 1. WdPage.petPic - right after safe (methods before callers)
P.rep('''    if (!((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_')) return "";
  }
  return id;
}""")
''', '''    if (!((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_')) return "";
  }
  return id;
}""")
# 0.2.10 (tools/wardrobe_0_2_10_patch.py 1; Skyy: "can we make this show the pet icon"): a pets:fn:petName label "Rare Crystal Golem Lv 12"
# -> SkyyPets' portrait Skyy_PetIcon_CrystalGolem (the label = rarity + PetKind.display(kind); "Skeleton Archer" = kind Skeleton); only an
# id the client knows (safe), else fb (the 0.2.9 icon) - an unknown kind / an older SkyyPets / an odd label never gives a client warning
M(page, r"""
public static String petPic(String lab, String fb) {
  if (lab == null) return fb;
  String n = @PKG@.WdBridge.petSplit(lab)[0].trim();
  int sp = n.indexOf(' ');
  if (sp > 0 && "|Common|Uncommon|Rare|Epic|Legendary|Mythic|Unknown|".indexOf("|" + n.substring(0, sp) + "|") >= 0) n = n.substring(sp + 1).trim();
  if (n.length() == 0 || n.length() > 48) return fb;
  String k = n.replace(" ", "");
  if (k.equals("SkeletonArcher")) k = "Skeleton";
  String ic = safe("Skyy_PetIcon_" + k);
  if (ic.length() == 0 && n.indexOf(' ') > 0) ic = safe("Skyy_PetIcon_" + n.replace(' ', '_'));
  return ic.length() > 0 ? ic : fb;
}""")
''')
# 2. the loadout's picked Pet / Summon cell
P.rep('''        out[rk] = new String[] { pic, fit(sp[0], REF_NAME, true), fit(sn + (sp[1].length() > 0 ? " - " + sp[1] : ""), REF_SUB, false), "0", lab + ": Equip puts it in your " + what + " slot." };''',
      '''        out[rk] = new String[] { petPic(lab, pic), fit(sp[0], REF_NAME, true), fit(sn + (sp[1].length() > 0 ? " - " + sp[1] : ""), REF_SUB, false), "0", lab + ": Equip puts it in your " + what + " slot." };   // 0.2.10: its own icon''')
# 2. the picker rows (pet + summon slot)
P.rep('''      out.add(new Object[] { p0 + pr[0], icon, Integer.valueOf(pr[0].equals(sel) ? 1 : 0), "", fit(sp[0], NAME_MAX, true), fit(where, SUB_MAX, false), sp[1], col });''',
      '''      out.add(new Object[] { p0 + pr[0], petPic(pr[1], icon), Integer.valueOf(pr[0].equals(sel) ? 1 : 0), "", fit(sp[0], NAME_MAX, true), fit(where, SUB_MAX, false), sp[1], col });   // 0.2.10: its own icon''')
assert P.s.count("registerCommand(") == REG0 and P.s.count("registerSystem(") == SYS0, "0.2.10 adds no command / system"
assert P.s.count("petPic(") == 3, "petPic: defined once, used in the cell + the picker rows"
P.finish()

# ====================================================================================================================== THE TEST
T = Patch(os.path.join(HERE, "test_skyywardrobe_0.2.9.py"), os.path.join(HERE, "test_skyywardrobe_0.2.10.py"), "test")
assert T.has('VERSION = "0.2.9"\n') and not T.has("Skyy_PetIcon_")
T.rep('"""Harness for SkyyWardrobe 0.2.9 (', '''"""Harness for SkyyWardrobe 0.2.10 (tools/wardrobe_0_2_10_patch.py; Skyy: "can we make this show the pet icon").
Derived from test_skyywardrobe_0.2.9.py: EVERY 0.2.9 section runs again on the 0.2.10 jar, plus:
  PI  (inside W, after W3) the test asset map holds a Skyy_PetIcon_<Kind> item for every kind SkyyPets 0.4.4 builds (KINDS + KINDS_043,
      read from SkyyPets/build_skyypets_0.4.4.py) EXCEPT Gecko (= an older / missing portrait). WdPage.petPic: each kind's label (rarity +
      SkyyPets' display name, Skeleton = "Skeleton Archer") -> Skyy_PetIcon_<Kind>; Gecko (no item) -> the fallback; an unknown kind
      ("Epic Dragon"), a null / empty / odd label (a quote, too long) -> the fallback; a label without rarity word still works. The page:
      the picked Pet cell + the picker rows carry Skyy_PetIcon_Wolf / Rabbit / Bear (no Farming_Collar); an unknown kind in the list =
      Farming_Collar (no empty ItemId); the page passes SUI.assert_menu_page + check_page + check_sky_paths (the kit checks)
  C   class compare 0.2.9 -> 0.2.10 (--base): no class added; WdPage + petPic only (refViews / refList: bodies)
  Repro: python SkyyWardrobe/test_skyywardrobe_0.2.10.py --jar SkyyWardrobe/SkyyWardrobe-0.2.9.jar  -> PI fails (every pet = the collar)
The 0.2.9 harness text follows:
Harness for SkyyWardrobe 0.2.9 (''')
T.rep('VERSION = "0.2.9"\n', 'VERSION = "0.2.10"\n')
T.rep('BASE = os.path.abspath(arg("--base", os.path.join(HERE, "SkyyWardrobe-0.2.8.jar")))  # 0.2.9: the class compare (the SET pin)',
      'BASE = os.path.abspath(arg("--base", os.path.join(HERE, "SkyyWardrobe-0.2.9.jar")))  # 0.2.10: the class compare (the SET pin)')
T.rep('SCRATCH = os.path.abspath(arg("--dir", os.path.join(TOOLS, "dev", "scratch", "reqfood", "w029")))',
      'SCRATCH = os.path.abspath(arg("--dir", os.path.join(TOOLS, "dev", "scratch", "ward10", "w0210")))')
T.rep('''    "SkyyFishing_Rod_Bamboo": ("plain", 1), "Tool_Watering_Can": ("plain", 1),
}
''', '''    "SkyyFishing_Rod_Bamboo": ("plain", 1), "Tool_Watering_Can": ("plain", 1),
}
# 0.2.10 PI: SkyyPets 0.4.4's pet kinds (read only from its build script) + their portrait items Skyy_PetIcon_<Kind>, all but Gecko
# (= a kind whose portrait the loaded SkyyPets lacks); KIND_NAMES = SkyyPets' display names that are not the split kind id
_PSRC = open(os.path.join(ROOT, "SkyyPets", "build_skyypets_0.4.4.py"), encoding="utf-8").read()
PET_KINDS = re.findall(r'^\\s+\\("([A-Za-z]+)", "(?:Farming|Mining|Foraging|Combat|Exploration)", "(?:Common|Uncommon|Rare|Epic|Legendary|Mythic)",', _PSRC, re.M)
PET_NAMES = __import__("ast").literal_eval(re.search(r"^KIND_NAMES = (\\{.*\\})$", _PSRC, re.M).group(1))
del _PSRC
assert len(PET_KINDS) >= 31 and len(set(PET_KINDS)) == len(PET_KINDS) and {"Rabbit", "Wolf", "Bear", "Skeleton", "CrystalGolem", "Gecko"} <= set(PET_KINDS), PET_KINDS
PET_NOICON = "Gecko"
ITEMS.update(("Skyy_PetIcon_" + k_, ("plain", 1)) for k_ in PET_KINDS if k_ != PET_NOICON)
''')
assert T.has("import os, sys, json, shutil, zipfile, subprocess, hashlib, time, re, random\n"), "the harness imports re"
PI_TEST = r'''
        # ============================================================ PI 0.2.10 each pet shows its own icon (Skyy: "can we make this show the pet icon")
        WPg = JClass(PKG + "WdPage")
        FB = "Farming_Collar"

        def pdisp(k_):
            """SkyyPets PetKind.display: a NAMES entry, else the id split before each capital that follows a lower-case letter"""
            if k_ in PET_NAMES:
                return PET_NAMES[k_]
            return re.sub(r"(?<=[a-z])(?=[A-Z])", " ", k_).replace("_", " ")
        rar_ = ["Common", "Uncommon", "Rare", "Epic", "Legendary", "Mythic"]
        bad_ = []
        for i_, k_ in enumerate(PET_KINDS):
            lab_ = "%s %s Lv %d" % (rar_[i_ % 6], pdisp(k_), i_ + 1)
            got_ = str(WPg.petPic(lab_, FB))
            exp_ = FB if k_ == PET_NOICON else "Skyy_PetIcon_" + k_
            if got_ != exp_:
                bad_.append((lab_, got_, exp_))
        K.check(not bad_, "PI icon id per kind: every SkyyPets kind's label -> Skyy_PetIcon_<Kind> (Skeleton Archer -> Skeleton) (%d kinds; bad %s)" % (len(PET_KINDS), bad_[:4]))
        K.check(str(WPg.petPic("Common Gecko Lv 1", FB)) == FB and str(WPg.petPic("Common Gecko Lv 1", "")) == "",
                "PI the fallback: a kind whose portrait item the client does not know -> the fallback icon (never an unknown id)")
        odd_ = [None, "", "Lv 3", "Epic Dragon Lv 2", "Rare", 'Rare Wo"lf Lv 1', "Rare Wolf; X Lv 1", "Mythic " + "W" * 60 + " Lv 1", "Rare Unknown Thing Lv 4"]
        K.check(all(str(WPg.petPic(o_, FB)) == FB for o_ in odd_),
                "PI an unknown kind / an empty, odd or too long label -> the fallback (%s)" % [str(WPg.petPic(o_, FB)) for o_ in odd_])
        K.check(str(WPg.petPic("Wolf Lv 3", FB)) == "Skyy_PetIcon_Wolf" and str(WPg.petPic("Unknown Crystal Golem", FB)) == "Skyy_PetIcon_CrystalGolem"
                and str(WPg.petPic("Legendary Skeleton Knight Lv 80", FB)) == "Skyy_PetIcon_SkeletonKnight",
                "PI a label without a rarity word / without a level / a two-word kind still finds the portrait")
        # the page: the picked Pet cell (Rare Wolf) + the picker rows of the pet slot
        wsel(0)
        text = rbuild()
        sets = wsets(text)
        K.check(sets.get("SkyyRqR0Nm") == "Rare Wolf" and "Skyy_PetIcon_Wolf" in text and "Skyy_PetIcon_Rabbit" in text and "Skyy_PetIcon_Bear" in text
                and FB not in text and 'ItemId: ""' not in text,
                "PI the picked Pet cell + the picker rows show each pet's own icon (Wolf, Rabbit, Bear), no collar left (%s)" % wcells())

        def pikit(what):
            b_, ev_ = UCB(), UEB()
            pgw.build(Pw.ref, b_, ev_, Pw.st)
            cm_ = [(None if c.type is None else str(c.type), None if c.selector is None else str(c.selector),
                    None if c.text is None else str(c.text), None if c.data is None else str(c.data)) for c in list(b_.getCommands())]
            apps_ = SUI.Appends([(None if s_ is None else s_.lstrip("#"), t_) for ty, s_, t_, d_ in cm_ if t_ is not None and ty and "Append" in ty])
            sets_ = [(s_, unq(d_)) for ty, s_, t_, d_ in cm_ if ty == "Set"]
            try:
                SUI.check_page(apps_, "Skyy")
                SUI.check_sky_paths(apps_, tab_icons=True)
                info_ = SUI.assert_menu_page(apps_, hub="storage", what=what, sets=sets_)
                return isinstance(info_, dict) and info_["rows"] == 2 and info_["subs"] == 1, info_
            except Exception as ex_:
                return False, str(ex_)
        ok_, info_ = pikit("pet picker with pet icons")
        K.check(ok_, "PI the page with the pet icons passes the kit checks (check_page + check_sky_paths + assert_menu_page) (%s)" % info_)
        # an unknown kind in the list -> the fallback icon, no empty ItemId; then back to the 0.2.9 fixture
        was_ = state["owned"]["pc000003"]
        state["owned"]["pc000003"] = "Epic Dragon Lv 5"
        pgw.petAt = 0
        text = rbuild()
        K.check(FB in text and "Skyy_PetIcon_Bear" not in text and "Skyy_PetIcon_Wolf" in text and 'ItemId: ""' not in text,
                "PI an unknown kind in the picker -> the fallback icon (the others keep theirs)")
        state["owned"]["pc000003"] = was_
        pgw.petAt = 0
        rbuild()
'''
T.rep('''        K.check(sets.get("SkyyRqR0Nm") == "Rare Wolf" and sets.get("SkyyRqR0Sb") == "Pet - Lv 12" and "Farming_Collar" in text,
                "W3 the Pet slot shows the collar icon + Rare Wolf + Pet - Lv 12 (%s)" % sets)\n''',
      '''        K.check(sets.get("SkyyRqR0Nm") == "Rare Wolf" and sets.get("SkyyRqR0Sb") == "Pet - Lv 12" and "Skyy_PetIcon_Wolf" in text,
                "W3 (0.2.10) the Pet slot shows the wolf's own icon + Rare Wolf + Pet - Lv 12 (%s)" % sets)\n''' + PI_TEST)
T.rep('''    K.check(not removed and added == [], "C 0.2.8 -> 0.2.9: no class added or removed (%s / %s)" % (removed, added))''',
      '''    K.check(not removed and added == [], "C 0.2.9 -> 0.2.10: no class added or removed (%s / %s)" % (removed, added))''')
T.rep('''    K.check(real == ["WdBridge"] and changed["WdBridge"] == {"-": 0, "+": 1}
            and "claimed(Ljava/lang/String;Ljava/lang/String;Ljava/util/HashMap;)Z" in new[PKG + "WdBridge"],
            "C (0.2.9) only WdBridge gains a member (+ claimed); depAllSkip: body only: %s %s" % (real, changed))''',
      '''    K.check(real == ["WdPage"] and changed["WdPage"] == {"-": 0, "+": 1}
            and "petPic(Ljava/lang/String;Ljava/lang/String;)Ljava/lang/String;" in new[PKG + "WdPage"],
            "C (0.2.10) only WdPage gains a member (+ petPic); refViews / refList: bodies only: %s %s" % (real, changed))''')
T.finish()
